#!/bin/bash
# Differential testing of the Rust fork against the C++ solver: both executables are run on the same inputs in all the three solver modes,
# and their complete outputs (verdicts and models) and text DRAT proofs (that is, every clause the solver has learnt, in order) must be byte-identical.
#
# Usage: scripts/diff_vs_cpp.sh [directory with extra .cnf files (e.g., generated by third_party/cnfuzzdd2013/cnfuzz_incr)] [extra solver parameters...]
# The instances in regression_instances are always used.
#
# The C++ solver has three sources of behavior, which is unspecified by the language/compiler (so the C++ solver itself may behave differently on different platforms):
#  (1) the order of equal elements after std::sort (clause deletion sorts the learnt clauses);
#  (2) the iteration order of std::unordered_map (the bit-compressed clause buffers of solver mode 2);
#  (3) floating-point contraction (fused multiply-add) of the VSIDS score updates, which some compilers apply by default (e.g., clang on AArch64).
# To compare apples to apples, the script builds a reference copy of the C++ solver, where these are pinned to what the Rust fork does:
#  (1) std::stable_sort (and, correspondingly, a copy of the Rust fork with a stable sort instead of sort_unstable_by);
#  (2) std::map, that is, ascending hash-id order, which is the order of the direct-index table of the Rust fork;
#  (3) -ffp-contract=off.
set -e
RUST_DIR="$(cd "$(dirname "$0")/.." && pwd)"
REPO_DIR="$(cd "$RUST_DIR/.." && pwd)"
WORK="${DIFF_WORK_DIR:-${TMPDIR:-/tmp}/intel_sat_diff_vs_cpp_$USER}"
CXX="${CXX:-c++}"
JOBS="${JOBS:-8}"
EXTRA_DIR=""
if [ -n "$1" ] && [ -d "$1" ]; then EXTRA_DIR="$1"; shift; fi

mkdir -p "$WORK/cpp" "$WORK/out"

# The reference C++ executable
if [ ! -x "$WORK/cpp/topor_release" ]; then
	cp "$REPO_DIR"/*.cc "$REPO_DIR"/*.hpp "$REPO_DIR"/*.h "$REPO_DIR"/Makefile "$WORK/cpp/"
	(
		cd "$WORK/cpp"
		perl -pi -e 's/^\t\tsort\(learntsSpan/\t\tstable_sort(learntsSpan/' TopiCompression.cc
		perl -pi -e 's/unordered_map<uint16_t, CBitArray>/map<uint16_t, CBitArray>/g' Topi.hpp TopiBitCompression.cc TopiCompression.cc Topi.cc
		perl -pi -e 's/bcSizeBefore \+ 1 >= m_BC\.max_load_factor\(\) \* m_BC\.bucket_count\(\)/false/' TopiBitCompression.cc
		perl -pi -e 's/#include <queue>/#include <queue>\n#include <map>/' Topi.hpp
		make r EXEC=topor CXX="$CXX" CFLAGS="-DSKIP_ZLIB -Wall -Wno-parentheses -std=c++20 -ffp-contract=off -O3 -D NDEBUG" -j"$JOBS" > build.log 2>&1 || { tail -20 build.log; exit 1; }
	)
fi

# The Rust executable with a stable sort of the learnt clauses
rm -rf "$WORK/rust"
mkdir -p "$WORK/rust"
cp -r "$RUST_DIR/src" "$RUST_DIR/Cargo.toml" "$WORK/rust/"
perl -pi -e 's/learntsSpan\.as_mut_slice\(\)\.sort_unstable_by/learntsSpan.as_mut_slice().sort_by/' "$WORK/rust/src/topi_compression.rs"
(cd "$WORK/rust" && CARGO_TARGET_DIR="$WORK/rust_target" cargo build --release 2>&1 | tail -1)

cat > "$WORK/one.sh" <<'EOS'
#!/bin/bash
WORK=$1; F=$2; M=$3; shift 3
B="$(basename "$F" .cnf)_m$M"
"$WORK/cpp/topor_release" "$F" /topor_tool/solver_mode $M /topor_tool/text_drat_file "$WORK/out/$B.cpp.drat" "$@" > "$WORK/out/$B.cpp.out" 2>&1; echo "exit $?" >> "$WORK/out/$B.cpp.out"
"$WORK/rust_target/release/intel_sat_solver" "$F" /topor_tool/solver_mode $M /topor_tool/text_drat_file "$WORK/out/$B.rs.drat" "$@" > "$WORK/out/$B.rs.out" 2>&1; echo "exit $?" >> "$WORK/out/$B.rs.out"
# The executables echo their parameters, including the name of the DRAT file
if cmp -s <(grep -v text_drat_file "$WORK/out/$B.cpp.out") <(grep -v text_drat_file "$WORK/out/$B.rs.out") && cmp -s "$WORK/out/$B.cpp.drat" "$WORK/out/$B.rs.drat"; then
	echo "OK $B"; rm -f "$WORK/out/$B".*
else
	echo "DIFF $B"
fi
EOS
chmod +x "$WORK/one.sh"

RES=0
for M in 0 1 2; do
	SUMMARY=$( (ls "$REPO_DIR"/regression_instances/*.cnf; [ -n "$EXTRA_DIR" ] && ls "$EXTRA_DIR"/*.cnf) | xargs -P "$JOBS" -I{} "$WORK/one.sh" "$WORK" {} $M "$@" | sort | awk '{c[$1]++; if ($1 == "DIFF") print} END {printf "solver mode: identical %d, different %d\n", c["OK"], c["DIFF"]}')
	echo "$SUMMARY" | sed "s/^solver mode:/solver mode $M:/"
	if echo "$SUMMARY" | grep -q "^DIFF"; then RES=1; fi
done
[ $RES -eq 0 ] || echo "The differing outputs are in $WORK/out"
exit $RES
